'use client'

import { useEffect, useState } from 'react'
import gsap from 'gsap'
import { createTransition } from './transition-core'
import { ZipperRig } from './zipper-rig'
import { DEFAULT_PITCH, DEFAULT_HEAD } from './zipper-art'
import './transitions.css'

export type ZipperOptions = {
  /** Metal and tape colours. Presets ship as classes; 'custom' leaves your own CSS alone. */
  palette: 'nickel' | 'steel' | 'brass' | 'gunmetal' | 'copper' | 'custom'
  /** Multiplies the whole timeline. Above 1 is faster. */
  speed: number
  /** Seconds the screen stays sealed before unzipping. The route swaps here. */
  sealHold: number
  /** Seconds the slider takes to run back down. */
  unzip: number
  /** Vertical spacing between teeth — the chain's density. */
  pitch: number
  /** Tooth height. Overlap with its neighbour is head - pitch/2. */
  head: number
  /** How far each panel travels outward, as a percentage of its own width. */
  slide: number
}

const DEFAULTS: ZipperOptions = {
  palette: 'nickel',
  speed: 1,
  sealHold: 1,
  unzip: 1.85,
  pitch: DEFAULT_PITCH,
  head: DEFAULT_HEAD,
  slide: 100,
}

type State = { zip: number; swing: number }

/**
 * The rig renders from two numbers, so the phases only have to drive those.
 * A module-level setter is enough of a bridge — the overlay is mounted once and
 * there is never more than one navigation in flight.
 */
let push: ((v: State) => void) | null = null

function ZipperOverlay({ options }: { options: ZipperOptions }) {
  const [v, setV] = useState<State>({ zip: 0, swing: 1 })
  useEffect(() => {
    push = setV
    return () => {
      push = null
    }
  }, [])

  const cls = options.palette === 'custom' ? undefined : `zip-${options.palette}`
  return (
    <div className={cls} style={{ display: 'contents' }}>
      <ZipperRig
        zip={v.zip}
        swing={v.swing}
        tuning={{ pitch: options.pitch, head: options.head, slide: options.slide }}
      />
    </div>
  )
}

/** A zip catches, gives, catches again, then runs away once properly engaged. */
const CLOSING = [
  { to: 0.17, dur: 0.2, ease: 'power2.out' },
  { hold: 0.13 },
  { to: 0.36, dur: 0.18, ease: 'power2.out' },
  { hold: 0.1 },
  { to: 1, dur: 0.58, ease: 'power1.in' },
] as const

export const ZipperTransition = createTransition<ZipperOptions>({
  timeout: 12000,
  defaults: DEFAULTS,
  overlay: (options) => <ZipperOverlay options={options} />,

  setup: () => push?.({ zip: 0, swing: 1 }),

  leave: ({ options, done }) => {
    const v: State = { zip: 0, swing: 1 }
    const tl = gsap.timeline({ onUpdate: () => push?.({ ...v }), onComplete: done })
    tl.to(v, { swing: 0, duration: 0.55, ease: 'power2.inOut' })
    for (const step of CLOSING) {
      if ('hold' in step) tl.to({}, { duration: step.hold })
      else tl.to(v, { zip: step.to, duration: step.dur, ease: step.ease })
    }
    tl.timeScale(options.speed)
    return () => tl.kill()
  },

  enter: ({ options, done }) => {
    const v: State = { zip: 1, swing: 0 }
    const tl = gsap.timeline({ onUpdate: () => push?.({ ...v }), onComplete: done })
    // sits sealed for a beat — that is when the route swaps — then one smooth
    // pull, because a zip never catches on the way open
    tl.to({}, { duration: options.sealHold })
      .to(v, { zip: 0, duration: options.unzip, ease: 'power2.inOut' })
      .to(v, { swing: 1, duration: 1.05, ease: 'power2.inOut' }, '-=0.2')
    tl.timeScale(options.speed)
    return () => tl.kill()
  },
})

'use client'

import { ZipperArt, Slider, ZIPPER_DIMS, DEFAULT_PITCH, DEFAULT_HEAD, sliderYFor } from './zipper-art'

export type RigTuning = {
  bands: number
  slide: number // % of its own width each panel travels outward — the main move
  angle: number // a little rotateY for depth; large values foreshorten the teeth to slivers
  lag: number // temporal: each band starts this much later than the one above
  fan: number // spatial: each band swings this much further than the one above
  pitch: number // vertical spacing between teeth — the chain's density
  head: number // tooth height; overlap with its neighbour is head - pitch/2
  droop: number // degrees of outward tip on the lowest band
  fall: number // px of sag on the lowest band
  shade: number // how much a panel darkens as it turns from the light
}

export const DEFAULT_TUNING: RigTuning = {
  bands: 1,
  slide: 100,
  angle: 8,
  lag: 0.05,
  fan: 0.08,
  pitch: DEFAULT_PITCH,
  head: DEFAULT_HEAD,
  droop: 4,
  fall: 30,
  shade: 0.18,
}

const bandSwing = (swing: number, i: number, t: RigTuning) => {
  const span = Math.max(0.05, 1 - (t.bands - 1) * t.lag)
  return Math.min(1, Math.max(0, (swing - i * t.lag) / span))
}

function Panel({
  side,
  zip,
  swing,
  t,
}: {
  side: 'left' | 'right'
  zip: number
  swing: number
  t: RigTuning
}) {
  const dir = side === 'left' ? -1 : 1

  return (
    <div className="zip-panel" style={{ [side]: 0, transformStyle: 'preserve-3d' }}>
      {Array.from({ length: t.bands }, (_, i) => {
        const s = bandSwing(swing, i, t)
        const depth = t.bands === 1 ? 1 : i / (t.bands - 1)
        return (
          <div
            key={i}
            className="zip-band"
            style={{
              top: `${(i * 100) / t.bands}%`,
              height: `${100 / t.bands}%`,
              transformOrigin: `${side} center`,
              transform: `translateX(${dir * s * t.slide * (1 + i * t.fan)}%)
                          rotateY(${dir * s * t.angle}deg)
                          rotateZ(${dir * s * t.droop * depth}deg)
                          translateY(${s * t.fall * depth}px)`,
              filter: `brightness(${1 - s * t.shade * (0.4 + 0.6 * depth)})`,
            }}
          >
            <div
              className="zip-band-art"
              style={{
                width: '200%',
                [side]: 0,
                top: `-${i * 100}%`,
                height: `${t.bands * 100}%`,
              }}
            >
              <ZipperArt progress={zip} showSlider={false} pitch={t.pitch} head={t.head} />
            </div>
          </div>
        )
      })}
    </div>
  )
}

export function ZipperRig({
  zip,
  swing,
  tuning,
}: {
  zip: number
  swing: number
  tuning?: Partial<RigTuning>
}) {
  const t = { ...DEFAULT_TUNING, ...tuning }
  const { W, H } = ZIPPER_DIMS
  const sliderY = sliderYFor(zip)

  return (
    <div
      className="zip-rig"
      style={{ perspective: '1400px', perspectiveOrigin: '50% 45%' }}
    >
      <Panel side="left" zip={zip} swing={swing} t={t} />
      <Panel side="right" zip={zip} swing={swing} t={t} />

      {/* The slider belongs to neither panel once they hinge apart, so it rides
          in its own layer, and rides out through the bottom as the panels
          leave rather than dissolving in place — a slider that fades reads as a
          bug, not as leaving. It leaves the way it came: the zip opens
          downward, so by then the slider is parked at the bottom. Reuses the
          #metal gradient the panels already registered in the document. */}
      <svg
        viewBox={`0 0 ${W} ${H}`}
        preserveAspectRatio="xMidYMid slice"
        className="zip-slider-layer"
        style={{ transform: `translateY(${swing * 42}%)` }}
      >
        <Slider y={sliderY} />
      </svg>
    </div>
  )
}

/**
 * Zipper artwork.
 *
 * No geometry, only shading: a specular band along each tooth's top edge, a
 * contact shadow beneath, and a slider with a lit top face.
 *
 * progress: 0 = fully open, 1 = fully closed. A zip closes upward — the slider
 * parks at the bottom and seals toward the top, the way a jacket does — so the
 * chain is meshed below it and still parted above.
 */

/**
 * The box is deliberately close to a real viewport. preserveAspectRatio="slice"
 * scales by max(containerW/W, containerH/H), so a small box magnifies the
 * artwork on a large screen — a 420-wide box lands at 4.5x on a 1900px display,
 * which is what made the teeth huge and soft at full size.
 */
const W = 1100
const H = 700
const CX = W / 2

export const DEFAULT_PITCH = 18 // vertical distance between teeth on one side
const BASE = 9 // tooth height where it meets the tape
/**
 * Tooth height. Meshed teeth are drawn over one another, so consecutive teeth
 * overlap by head - pitch/2 and that overlap is the interlock. Too little and
 * the chain reads as separate blocks; too much and each tooth buries the lower
 * third of the one before it, which is where the dark core and the reflected
 * bounce live — the joined chain then looks flat next to the separated rows.
 */
export const DEFAULT_HEAD = 13
const LEN = 34 // how far a tooth reaches from its tape edge
const OVERLAP = 14 // how far past centre a meshed tooth crosses
const GAP = 60 // how far each tape sits from centre once fully parted
const TAPER = 150 // distance below the slider over which the rows fan apart

export const SLIDER_INSET = 40 // how far the parked slider sits from each edge

/**
 * Where the slider sits for a given progress. Exported because the rig draws
 * its own slider layer above the hinged panels — with the formula written out
 * twice the two could drift apart, and reversing the travel direction is
 * exactly the kind of change that would do it.
 */
export const sliderYFor = (progress: number) =>
  H - SLIDER_INSET - progress * (H - SLIDER_INSET * 2)
const SLIDER_W = 52
const SLIDER_H = 72

/**
 * How far apart the rows are at a given y. Zero below the slider, where the
 * chain is already meshed, then eased out to full over TAPER going up — the
 * rows funnel out of the slider's mouth rather than jumping to their final
 * width.
 */
const parting = (y: number, sliderY: number) => {
  if (y >= sliderY) return 0
  const t = Math.min(1, (sliderY - y) / TAPER)
  return 1 - (1 - t) * (1 - t) // easeOutQuad
}

const lerp = (a: number, b: number, t: number) => a + (b - a) * t

/** Flares toward the tip so meshed teeth visibly lock between their neighbours. */
const toothPath = (HEAD: number) => {
  const b = BASE / 2
  const h = HEAD / 2
  return `M 0 ${-b}
    L ${LEN * 0.44} ${-b}
    L ${LEN * 0.62} ${-h}
    L ${LEN - 2.5} ${-h}
    Q ${LEN} ${-h} ${LEN} ${-h + 2.5}
    L ${LEN} ${h - 2.5}
    Q ${LEN} ${h} ${LEN - 2.5} ${h}
    L ${LEN * 0.62} ${h}
    L ${LEN * 0.44} ${b}
    L 0 ${b} Z`
}

function Tooth({ x, y, flip, head: HEAD }: { x: number; y: number; flip?: boolean; head: number }) {
  const d = toothPath(HEAD)
  const h = HEAD / 2
  return (
    <g transform={`translate(${x} ${y}) ${flip ? 'scale(-1 1)' : ''}`}>
      <path d={d} fill="url(#metal)" />
      {/* shading along the length, so base and tip are not as bright as the belly */}
      <path d={d} fill="url(#form)" />
      {/* primary specular, faded at both ends so it has no hard terminator */}
      <rect x={LEN * 0.2} y={-h + 1.5} width={LEN * 0.7} height={1.1} rx={0.55} fill="url(#spec)" />
      {/* reflected light along the bottom edge — the main reason metal reads as
          metal rather than plastic */}
      <rect x={LEN * 0.3} y={h - 2.4} width={LEN * 0.5} height={1.1} rx={0.55} fill="url(#bounce)" />
      {/* highlight wrapping the flared head */}
      <rect x={LEN * 0.62} y={-h + 3.4} width={LEN * 0.36} height={HEAD - 7} rx={2.4} fill="url(#tip)" />
    </g>
  )
}

export function ZipperArt({
  progress = 1,
  view,
  showSlider = true,
  pitch: PITCH = DEFAULT_PITCH,
  head = DEFAULT_HEAD,
}: {
  progress?: number
  /** Vertical spacing between teeth on one side — the chain's density. */
  pitch?: number
  /** Tooth height. Overlap with the tooth before it is head - pitch/2. */
  head?: number
  /** Crop to a region, for inspecting the teeth up close. */
  view?: string
  /** Off when the rig draws the slider in its own layer, above the hinged panels. */
  showSlider?: boolean
}) {
  // Continuous across the whole range on purpose. Special-casing the ends made
  // the slider jump ~34 units the instant progress hit exactly 0 or 1, which
  // read as the travel stuttering backwards and repeating itself.
  const sliderY = sliderYFor(progress)

  // Tape inner edges follow the same taper the teeth do, so fabric and metal
  // fan out together instead of the tape stepping open in one jump.
  const edge: string[] = []
  for (let y = 0; y <= H; y += 8) {
    edge.push(`${lerp(CX, CX - GAP, parting(y, sliderY))} ${y}`)
  }
  const leftTape = `M 0 0 L ${edge.join(' L ')} L 0 ${H} Z`
  const rightEdge = edge.map((p) => {
    const [x, y] = p.split(' ').map(Number)
    return `${2 * CX - x} ${y}`
  })
  const rightTape = `M ${W} 0 L ${rightEdge.join(' L ')} L ${W} ${H} Z`

  // Alternating draw order is what makes a closed zip read as one chain rather
  // than two columns lying side by side — each tooth overlaps the one before it.
  const teeth = []
  for (let i = 0; i < Math.ceil(H / PITCH) + 1; i++) {
    const ly = i * PITCH
    const ry = i * PITCH + PITCH / 2 // half-pitch offset so the rows interleave
    teeth.push(
      <Tooth key={`l${i}`} head={head} y={ly} x={lerp(CX + OVERLAP, CX - GAP, parting(ly, sliderY)) - LEN} />,
      <Tooth
        key={`r${i}`}
        head={head}
        y={ry}
        flip
        x={lerp(CX - OVERLAP, CX + GAP, parting(ry, sliderY)) + LEN}
      />,
    )
  }

  return (
    <svg viewBox={view ?? `0 0 ${W} ${H}`} className="zip-fill" preserveAspectRatio="xMidYMid slice">
      <defs>
        {/* Real metal is not a linear ramp: a bright rim, a fast falloff, a dark
            core, then light bouncing back up off whatever is underneath. */}
        {/* A thin rim rather than a bright plateau, and a bottom that stops at
            metal-lo instead of near-black. The previous ramp ended almost black
            and began almost white, so every tooth boundary read as an outline. */}
        <linearGradient id="metal" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="var(--zip-metal-edge, #211f1c)" />
          <stop offset="5%" stopColor="var(--zip-metal-lo, #4a453e)" />
          <stop offset="13%" stopColor="var(--zip-metal, #d7d2c8)" />
          <stop offset="34%" stopColor="var(--zip-metal, #d7d2c8)" />
          <stop offset="56%" stopColor="var(--zip-metal-mid, #8f887c)" />
          <stop offset="78%" stopColor="var(--zip-metal-edge, #211f1c)" />
          <stop offset="92%" stopColor="var(--zip-metal-mid, #8f887c)" />
          <stop offset="100%" stopColor="var(--zip-metal-lo, #4a453e)" />
        </linearGradient>
        <linearGradient id="spec" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="rgba(255,255,255,0)" />
          <stop offset="18%" stopColor="rgba(255,255,255,.95)" />
          <stop offset="52%" stopColor="rgba(255,255,255,.6)" />
          <stop offset="88%" stopColor="rgba(255,255,255,.1)" />
          <stop offset="100%" stopColor="rgba(255,255,255,0)" />
        </linearGradient>
        <linearGradient id="bounce" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="rgba(255,255,255,0)" />
          <stop offset="45%" stopColor="rgba(255,255,255,.22)" />
          <stop offset="100%" stopColor="rgba(255,255,255,0)" />
        </linearGradient>
        {/* Form along the tooth's length — dark where it sits in the tape, open
            through the middle, falling away again over the flared tip. Without
            this the ends are as bright as the belly and read as flat. */}
        <linearGradient id="form" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="rgba(0,0,0,.6)" />
          <stop offset="16%" stopColor="rgba(0,0,0,.12)" />
          <stop offset="58%" stopColor="rgba(0,0,0,0)" />
          <stop offset="84%" stopColor="rgba(0,0,0,.14)" />
          <stop offset="100%" stopColor="rgba(0,0,0,.4)" />
        </linearGradient>
        {/* the flared head is a rounded form and catches its own highlight */}
        <linearGradient id="tip" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="rgba(255,255,255,0)" />
          <stop offset="70%" stopColor="rgba(255,255,255,.3)" />
          <stop offset="100%" stopColor="rgba(255,255,255,0)" />
        </linearGradient>
        <linearGradient id="tape" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="var(--zip-tape-lo, #26262c)" />
          <stop offset="50%" stopColor="var(--zip-tape, #3d3d46)" />
          <stop offset="100%" stopColor="var(--zip-tape-lo, #26262c)" />
        </linearGradient>
        {/* One filter per row rather than per tooth — the rows interleave, so
            each already casts onto the other, and it is 2 filters not 60. */}
        <radialGradient id="castSoft">
          <stop offset="0%" stopColor="rgba(0,0,0,.5)" />
          <stop offset="60%" stopColor="rgba(0,0,0,.22)" />
          <stop offset="100%" stopColor="rgba(0,0,0,0)" />
        </radialGradient>
        <filter id="cast" x="-25%" y="-25%" width="160%" height="160%">
          <feDropShadow dx="0.3" dy="1.1" stdDeviation="0.85" floodColor="#000" floodOpacity="0.62" />
        </filter>
      </defs>

      <path d={leftTape} fill="url(#tape)" />
      <path d={rightTape} fill="url(#tape)" />
      <g filter="url(#cast)">{teeth}</g>
      {showSlider && <Slider y={sliderY} />}
    </svg>
  )
}

/**
 * Wide mouth up, narrow end down — the two rows feed in from the parted side
 * above and the single meshed chain leaves below. This has to follow the travel
 * direction: a slider pointing the wrong way makes the parted teeth look
 * detached from it.
 */
export function Slider({ y }: { y: number }) {
  const w = SLIDER_W
  const h = SLIDER_H
  const neck = 17
  return (
    <g transform={`translate(${CX} ${y})`}>
      <ellipse cx={0} cy={h / 2 - 16} rx={w / 2 + 8} ry={13} fill="url(#castSoft)" />
      <path
        d={`M ${-neck / 2} ${h / 2}
            L ${neck / 2} ${h / 2}
            L ${neck / 2 + 3} ${h / 2 - 16}
            L ${w / 2} ${-h / 2 + 10}
            Q ${w / 2} ${-h / 2} ${w / 2 - 10} ${-h / 2}
            L ${-w / 2 + 10} ${-h / 2}
            Q ${-w / 2} ${-h / 2} ${-w / 2} ${-h / 2 + 10}
            L ${-neck / 2 - 3} ${h / 2 - 16} Z`}
        fill="url(#metal)"
      />
      {/* lit face on top — now the wide mouth, so it runs the full width */}
      <path
        d={`M ${-w / 2 + 10} ${-h / 2 + 2} L ${w / 2 - 10} ${-h / 2 + 2} L ${w / 2 - 13} ${-h / 2 + 10} L ${-w / 2 + 13} ${-h / 2 + 10} Z`}
        fill="url(#spec)"
      />
      {/* pull tab still hangs off the bottom — gravity does not flip with the zip */}
      <rect x={-4} y={h / 2 - 12} width={8} height={16} rx={3} fill="url(#metal)" />
      <rect
        x={-13}
        y={h / 2 + 2}
        width={26}
        height={38}
        rx={7}
        fill="none"
        stroke="url(#metal)"
        strokeWidth={6}
      />
    </g>
  )
}

export const ZIPPER_DIMS = { W, H, CX }

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef, type ReactNode } from 'react'

/** Passed to every phase. Query your own nodes out of `overlay`. */
export type TransitionContext<O> = {
  overlay: HTMLDivElement
  /** Whatever the component was given, merged over the config defaults. */
  options: O
  /** Call when the animation is finished. The navigation waits for this. */
  done: () => void
}

/** A phase may return a cleanup function, called if the phase is interrupted. */
export type Phase<O> = (ctx: TransitionContext<O>) => void | (() => void)

export type TransitionConfig<O> = {
  /**
   * Markup that covers the screen. A function when the markup itself depends on
   * the options; otherwise rendered once and reused for every navigation.
   */
  overlay: ReactNode | ((options: O) => ReactNode)
  /** Values a consumer may override as props. */
  defaults: O
  /** Runs once after mount — measure paths, set starting state. */
  setup?: (overlay: HTMLDivElement, options: O) => void
  /** Plays before the route changes. */
  leave: Phase<O>
  /** Plays after the route changes. */
  enter: Phase<O>
  /**
   * Failsafe. If a phase never calls done() the navigation continues anyway,
   * so a broken animation can never trap someone behind an opaque overlay.
   */
  timeout?: number
}

const DEFAULT_TIMEOUT = 4000

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Turns a transition config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Engine-agnostic: the phases can use GSAP, Motion, or raw WAAPI. The core only
 * cares that `done()` eventually gets called.
 */
export function createTransition<O extends object>(config: TransitionConfig<O>) {
  const timeout = config.timeout ?? DEFAULT_TIMEOUT

  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const ref = useRef<HTMLDivElement>(null)
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O

    // Phases read this rather than closing over a stale render's options.
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      if (ref.current) config.setup?.(ref.current, latest.current)
    }, [])

    const run = (phase: Phase<O>) => (next: () => void) => {
      const overlay = ref.current

      // No overlay yet, or the user asked for less motion — navigate straight through.
      if (!overlay || prefersReducedMotion()) {
        next()
        return
      }

      let settled = false
      const done = () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        next()
      }
      const timer = setTimeout(() => {
        console.warn(`[transition] phase exceeded ${timeout}ms, continuing`)
        done()
      }, timeout)

      let cleanup: void | (() => void)
      try {
        cleanup = phase({ overlay, options: latest.current, done })
      } catch (error) {
        console.error('[transition] phase threw, continuing', error)
        done()
      }

      return () => {
        clearTimeout(timer)
        settled = true
        cleanup?.()
      }
    }

    return (
      <TransitionRouter auto leave={run(config.leave)} enter={run(config.enter)}>
        <div ref={ref} className="transition-overlay" aria-hidden>
          {typeof config.overlay === 'function' ? config.overlay(options) : config.overlay}
        </div>
        {children}
      </TransitionRouter>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

.transition-overlay svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

/*
 * The fire is its own colour, not the pages'. The outgoing page is masked away
 * inside the burn front, the incoming page is masked to show only inside a
 * slightly smaller front, and this ramp sits behind both — so what you see in
 * the gap between them is the fire itself.
 *
 * The ramp is anchored to the band rather than the origin. Anchored to the
 * origin, the visible annulus samples the cold end of the gradient once the
 * front is halfway out, and the fire goes dull.
 */
:root,
.burn-ember {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
}

/* Magnesium burns brilliant white and almost colourless — the point of it is
   that there is no hue, so this stays neutral all the way down. */
.burn-magnesium {
  --burn-core: #ffffff;
  --burn-hot: #f6f7f8;
  --burn-mid: #a9aeb4;
  --burn-edge: #34383d;
}

.burn-cold {
  --burn-core: #ddf5ff;
  --burn-hot: #33c9ff;
  --burn-mid: #0a5fd4;
  --burn-edge: #04123f;
}

.burn-toxic {
  --burn-core: #f4ffd9;
  --burn-hot: #c6ff3d;
  --burn-mid: #46b81a;
  --burn-edge: #0d3a0a;
}

.vt-film-burn::view-transition-group(root) {
  animation: none;
  background:
    radial-gradient(
      circle at var(--burn-x, 50%) var(--burn-y, 50%),
      var(--burn-core) calc(var(--burn-cut, 0px) - var(--burn-band, 64px)),
      var(--burn-hot) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.68),
      var(--burn-mid) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.3),
      var(--burn-edge) var(--burn-cut, 0px),
      var(--burn-edge) 100%
    );
}

.vt-film-burn::view-transition-image-pair(root) {
  isolation: auto;
}

/* The browser stacks the incoming snapshot above the outgoing one, so the
   outgoing page has to be lifted for its mask to read as a hole rather than as
   nothing at all. */
.vt-film-burn::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 1;
  mask: url(#burn-mask-new);
  -webkit-mask: url(#burn-mask-new);
}

.vt-film-burn::view-transition-old(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 2;
  mask: url(#burn-mask-old);
  -webkit-mask: url(#burn-mask-old);
}

/* ---------- riser ---------- */

/*
 * Nothing here is driven from JavaScript. The outgoing page is pushed back and
 * dimmed, the incoming page is unmasked over it, and the browser runs both off
 * the stylesheet — which is why this one needs no dependencies at all.
 */
.vt-riser::view-transition-group(root) {
  animation: none;
}

.vt-riser::view-transition-image-pair(root) {
  isolation: auto;
}

/*
 * Origin at the arriving edge, not the centre. Scaling about the centre pulls
 * the outgoing page away from that edge, so it reads as sliding off rather than
 * settling behind. Anchored to the edge it recedes into the space the incoming
 * page is about to occupy, and stays visible above it the whole way.
 */
.vt-riser::view-transition-old(root) {
  animation: riser-recede var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 1;
  transform-origin: var(--riser-origin, 50% 0%);
}

/*
 * The incoming page slides in as a card rather than being clipped into view. A
 * clip reveal has no edge and casts nothing, so there is no cue that one page
 * is above the other — the shadow is what actually sells the layering.
 */
.vt-riser::view-transition-new(root) {
  animation: riser-arrive var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 2;
  box-shadow: var(--riser-shadow, 0 -24px 60px rgba(0, 0, 0, 0.45));
}

/* The tilt is what makes it read as depth rather than a shrink — the page
   leans away from you as it drops back. */
/*
 * Perspective distance matters as much as the angle. At 1400px a 6deg lean
 * narrows the far edge by about 6%, which reads as nothing at all; 900px and
 * 14deg takes it to 80%, which is unmistakably a page leaning away.
 */
@keyframes riser-recede {
  to {
    opacity: var(--riser-dim, 0.35);
    transform: perspective(var(--riser-perspective, 800px))
      translate3d(var(--riser-out-x, 0), var(--riser-out-y, -8vh), 0)
      rotateX(var(--riser-tilt-x, 18deg)) rotateY(var(--riser-tilt-y, 0deg))
      scale(var(--riser-depth, 0.82));
  }
}

@keyframes riser-arrive {
  from {
    transform: translate3d(var(--riser-in-x, 0), var(--riser-in-y, 100%), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/* The incoming page is unmasked from the edge it arrives at, and the outgoing
   page recedes the opposite way, so the two read as one movement. */
.riser-up {
  --riser-in-y: 100%;
  --riser-in-x: 0;
  --riser-shadow: 0 -24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 0%;
  --riser-out-y: calc(var(--riser-travel, 8vh) * -1);
  --riser-out-x: 0;
  --riser-tilt-x: var(--riser-tilt, 18deg);
  --riser-tilt-y: 0deg;
}

.riser-down {
  --riser-in-y: -100%;
  --riser-in-x: 0;
  --riser-shadow: 0 24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 100%;
  --riser-out-y: var(--riser-travel, 8vh);
  --riser-out-x: 0;
  --riser-tilt-x: calc(var(--riser-tilt, 18deg) * -1);
  --riser-tilt-y: 0deg;
}

.riser-left {
  --riser-in-y: 0;
  --riser-in-x: 100%;
  --riser-shadow: -24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 0% 50%;
  --riser-out-x: calc(var(--riser-travel-x, 8vw) * -1);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: calc(var(--riser-tilt, 18deg) * -1);
}

.riser-right {
  --riser-in-y: 0;
  --riser-in-x: -100%;
  --riser-shadow: 24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 100% 50%;
  --riser-out-x: var(--riser-travel-x, 8vw);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: var(--riser-tilt, 18deg);
}

@media (prefers-reduced-motion: reduce) {
  .vt-riser::view-transition-old(root),
  .vt-riser::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- push ---------- */

/*
 * Both pages travel the same direction, the outgoing one slower, so it is
 * overtaken rather than shoved off. Nothing but a transform on each snapshot
 * and a brightness on the one being covered — no JavaScript touches a frame.
 */

:root {
  /* Material 3's emphasized curve: leaves quickly, arrives gently. */
  --push-ease: cubic-bezier(0.2, 0, 0, 1);
}

.vt-push::view-transition-group(root) {
  animation: none;
}

.vt-push::view-transition-image-pair(root) {
  isolation: auto;
}

.vt-push::view-transition-old(root) {
  animation: push-recede var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 1;
}

.vt-push::view-transition-new(root) {
  animation: push-arrive var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 2;
  /* Reads the seam between the two pages while they overlap. */
  box-shadow: var(--push-shadow, -18px 0 48px rgba(0, 0, 0, 0.34));
}

/*
 * brightness rather than opacity: the outgoing page has the incoming one
 * already rendered behind it, so fading it out would cross-dissolve the two
 * instead of darkening one.
 */
@keyframes push-recede {
  to {
    transform: translate3d(var(--push-out-x, 0), var(--push-out-y, 0), 0);
    filter: brightness(var(--push-dim, 0.78));
  }
}

@keyframes push-arrive {
  from {
    transform: translate3d(var(--push-in-x, 100%), var(--push-in-y, 0), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

.push-left {
  --push-in-x: 100%;
  --push-in-y: 0;
  --push-out-x: calc(var(--push-parallax, 28%) * -1);
  --push-out-y: 0;
  --push-shadow: -18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-right {
  --push-in-x: -100%;
  --push-in-y: 0;
  --push-out-x: var(--push-parallax, 28%);
  --push-out-y: 0;
  --push-shadow: 18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-up {
  --push-in-x: 0;
  --push-in-y: 100%;
  --push-out-x: 0;
  --push-out-y: calc(var(--push-parallax, 28%) * -1);
  --push-shadow: 0 -18px 48px rgba(0, 0, 0, 0.34);
}

.push-down {
  --push-in-x: 0;
  --push-in-y: -100%;
  --push-out-x: 0;
  --push-out-y: var(--push-parallax, 28%);
  --push-shadow: 0 18px 48px rgba(0, 0, 0, 0.34);
}

@media (prefers-reduced-motion: reduce) {
  .vt-push::view-transition-old(root),
  .vt-push::view-transition-new(root) {
    animation: none;
  }
}
